import{_ as e,o as r,c as a,a2 as s}from"./chunks/framework.hw3Av5Vn.js";const u=JSON.parse('{"title":"Credits","description":"","frontmatter":{},"headers":[],"relativePath":"CREDITS.md","filePath":"CREDITS.md"}'),d={name:"CREDITS.md"};function o(n,t,i,l,c,h){return r(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to &quot;Credits&quot;">​</a></h1><p>In addition to llamatron, Copyright (C) 2026 Michael DeHaan, released under the GNU General Public License, version 3 or later, this code has benefitted from research and work from the open source projects below.</p><h2 id="code-llamatron-uses" tabindex="-1">Code llamatron Uses <a class="header-anchor" href="#code-llamatron-uses" aria-label="Permalink to &quot;Code llamatron Uses&quot;">​</a></h2><p>llamatron&#39;s built-in synths use other people&#39;s open work where it already models a sound well, only under licences compatible with llamatron&#39;s own. The implementations are llamatron&#39;s own, read from theirs, and a comment above every algorithm in the code names the work it follows and its licence.</p><table tabindex="0"><thead><tr><th>Work</th><th>Author</th><th>Licence</th><th>What llamatron uses</th></tr></thead><tbody><tr><td><a href="https://github.com/surge-synthesizer/sst-filters" target="_blank" rel="noreferrer">sst-filters</a></td><td>the Surge Synth Team, 2019 to 2025</td><td>GPL-3.0-or-later</td><td>The Sallen-Key filter&#39;s model of the resonant two-pole circuit, adapted there from Odin 2 (<code>src/backend/src/filters/sallen_key.rs</code>), and the Multimode&#39;s saturating band state, after its ResonanceWarp (<code>src/backend/src/filters/multimode.rs</code>)</td></tr><tr><td><a href="https://github.com/surge-synthesizer/sst-effects" target="_blank" rel="noreferrer">sst-effects</a></td><td>the Surge Synth Team</td><td>GPL-3.0-or-later</td><td>MultiTap&#39;s crossfade to a changed tap time: half the delay long, held between 10 and 500 ms, a change during a fade waiting for it to end (<code>src/backend/src/effects/multitap.rs</code>)</td></tr><tr><td><a href="http://ldesoras.free.fr/prod.html#src_hiir" target="_blank" rel="noreferrer">hiir</a></td><td>Laurent de Soras</td><td>WTFPL</td><td>The halfband that oversamples the saturating filters: its polyphase all-pass design&#39;s coefficients, after its Upsampler2x and Downsampler2x (<code>src/backend/src/dsp/oversample.rs</code>)</td></tr><tr><td><a href="https://github.com/Chowdhury-DSP/chowdsp_utils" target="_blank" rel="noreferrer">chowdsp_utils</a></td><td>Jatin Chowdhury</td><td>GPL-3.0 (its DSP modules)</td><td>MultiTap&#39;s Analog mode: the bucket-brigade device&#39;s input and output filters as sums of complex one-poles and their stepping at the clock&#39;s ticks, after Martin Holters and Julian Parker, &quot;A Combined Model for a Bucket Brigade Device and its Input and Output Filters&quot;, DAFx-18 (<code>src/backend/src/effects/bucket_brigade.rs</code>)</td></tr><tr><td><a href="https://github.com/TheWaveWarden/odin2" target="_blank" rel="noreferrer">Odin 2</a></td><td>TheWaveWarden</td><td>GPL-3.0-or-later</td><td>The resonant two-pole filter sst-filters adapted, after Will Pirkle&#39;s virtual-analog design</td></tr><tr><td><a href="https://github.com/pichenettes/eurorack/tree/master/streams" target="_blank" rel="noreferrer">Streams</a>, Mutable Instruments</td><td>Emilie Gillet, 2014</td><td>MIT</td><td>The vactrol&#39;s light history: a cell tiring under light and resting in the dark (<code>src/backend/src/envelopes/vactrol.rs</code>)</td></tr><tr><td><a href="https://github.com/pichenettes/stmlib" target="_blank" rel="noreferrer">stmlib</a></td><td>Emilie Gillet</td><td>MIT</td><td>The polyBLEP that smooths the jumps of the LFOs&#39;, Basic&#39;s, the SID pulse&#39;s and Asheville&#39;s waves, and the one-sample-delayed BLEP of the SID&#39;s hard sync (<code>src/backend/src/dsp/blep.rs</code>); the soft limit the OTA saturates through (<code>src/backend/src/filters/ota.rs</code>)</td></tr><tr><td><a href="https://github.com/pichenettes/eurorack/tree/master/plaits" target="_blank" rel="noreferrer">Plaits</a>, Mutable Instruments</td><td>Emilie Gillet, 2016</td><td>MIT</td><td>Asheville&#39;s variable-shape waves and its Snap, the detuning curve that settles on unison, fifths and octaves (<code>src/backend/src/oscillators/asheville.rs</code>), the band-limited hard sync of the SID (<code>src/backend/src/oscillators/sid.rs</code>), and Bitcrush&#39;s Rate, its holds falling between samples (<code>src/backend/src/effects/bitcrush.rs</code>)</td></tr><tr><td><a href="https://github.com/VCVRack/Fundamental" target="_blank" rel="noreferrer">VCV Fundamental</a></td><td>VCV and Andrew Belt</td><td>GPL-3.0-or-later</td><td>The OTA&#39;s saturating stages, each stage&#39;s gain scaled by its own saturation, after its VCF (<code>src/backend/src/filters/ota.rs</code>)</td></tr><tr><td><a href="https://github.com/libsidplayfp/resid" target="_blank" rel="noreferrer">reSID</a></td><td>Dag Lem, 2010</td><td>GPL-2.0-or-later</td><td>The SID engine&#39;s waveform converter: the uneven, unterminated resistor ladder its saw, triangle and noise go through (<code>src/backend/src/oscillators/tables.rs</code>)</td></tr><tr><td><a href="https://sourceforge.net/p/open303/code" target="_blank" rel="noreferrer">Open303</a></td><td>Robin Schmidt, www.rs-met.com, 2009</td><td>MIT</td><td>Oh3&#39;s saw and square, the coupling filters around the Diode filter, the Diode filter itself and its measured Env amount mapping (<code>src/backend/src/oscillators/acid.rs</code>, <code>src/backend/src/dsp/one_pole.rs</code> and <code>src/backend/src/filters/diode.rs</code>)</td></tr></tbody></table><h2 id="research-consulted" tabindex="-1">Research Consulted <a class="header-anchor" href="#research-consulted" aria-label="Permalink to &quot;Research Consulted&quot;">​</a></h2><p>These projects were read to check how sounds really behave and to choose designs, as references beside the instruments&#39; own manuals; where llamatron takes an algorithm from one, it moves to the table above.</p><table tabindex="0"><thead><tr><th>Project</th><th>Licence</th><th>What was read</th></tr></thead><tbody><tr><td><a href="https://github.com/pichenettes/eurorack" target="_blank" rel="noreferrer">Mutable Instruments eurorack</a></td><td>MIT (the STM32 modules), GPL-3.0-or-later (Edges, Grids, Branches)</td><td>Oscillators, filters, envelopes and effects across Plaits, Braids, Rings, Elements, Clouds, Beads, Warps, Tides, Stages and Peaks</td></tr><tr><td><a href="https://github.com/VCVRack/Fundamental" target="_blank" rel="noreferrer">VCV Fundamental</a></td><td>GPL-3.0-or-later</td><td>The VCO&#39;s minBLEP and sync, the VCF&#39;s oversampling, the wavetable VCO, the ADSR</td></tr><tr><td><a href="https://github.com/VCVRack/Befaco" target="_blank" rel="noreferrer">Befaco for VCV</a></td><td>GPL-3.0-or-later</td><td>Through-zero FM, DPW waves and ADAA wavefolding</td></tr><tr><td><a href="https://github.com/bogaudio/BogaudioModules" target="_blank" rel="noreferrer">Bogaudio Modules</a></td><td>GPL-3.0-or-later</td><td>Oscillators, multimode filters and the low-pass gate</td></tr><tr><td><a href="https://github.com/VCVRack/AudibleInstruments" target="_blank" rel="noreferrer">Audible Instruments</a></td><td>GPL-3.0-or-later</td><td>The Ripples OTA filter emulation</td></tr><tr><td><a href="https://github.com/surge-synthesizer/surge" target="_blank" rel="noreferrer">Surge XT</a></td><td>GPL-3.0-or-later</td><td>Its oscillators, including the Modern oscillator&#39;s DPW</td></tr><tr><td><a href="https://github.com/surge-synthesizer/sst-waveshapers" target="_blank" rel="noreferrer">sst-waveshapers</a></td><td>GPL-3.0</td><td>Wavefolders with antiderivative anti-aliasing</td></tr><tr><td><a href="https://github.com/ddiakopoulos/MoogLadders" target="_blank" rel="noreferrer">Ladder models</a></td><td>each model its own: ISC, LGPL-3.0, Unlicense, BSD</td><td>Ladder filter models, among them the improved D&#39;Angelo and Välimäki model</td></tr><tr><td><a href="https://github.com/libsidplayfp/libsidplayfp" target="_blank" rel="noreferrer">libsidplayfp</a></td><td>GPL-2.0-or-later</td><td>The SID chip&#39;s waveforms, envelopes and filter</td></tr></tbody></table><h2 id="public-domain-music" tabindex="-1">Public Domain Music <a class="header-anchor" href="#public-domain-music" aria-label="Permalink to &quot;Public Domain Music&quot;">​</a></h2><p>llamatron&#39;s song wizard is built on music theory measured from public domain music, in files that carry no restricting licence of their own: scores and traditional tunes were read for how real melodies, harmonies and phrases behave, and only those measurements went into the program. None of the music is shipped with llamatron. Classical and traditional pieces from these collections also appear in some of the demos, such as the mashups. The song wizard will soon import downloaded corpus songs quickly, as patterns and scenes to start from.</p><table tabindex="0"><thead><tr><th>Collection</th><th>Edited or kept by</th><th>Terms</th><th>What it holds</th><th>Folder</th></tr></thead><tbody><tr><td><a href="https://github.com/craigsapp/joplin" target="_blank" rel="noreferrer">Scott Joplin&#39;s piano works</a></td><td>Craig Stuart Sapp</td><td>public domain music, the encoding its editor&#39;s</td><td>Ragtime</td><td><code>joplin</code></td></tr><tr><td><a href="https://github.com/craigsapp/chopin-mazurkas" target="_blank" rel="noreferrer">Chopin&#39;s mazurkas</a></td><td>Craig Stuart Sapp</td><td>public domain music, the encoding its editor&#39;s</td><td>Piano</td><td><code>chopin-mazurkas</code></td></tr><tr><td><a href="https://github.com/craigsapp/haydn-piano-sonatas" target="_blank" rel="noreferrer">Haydn&#39;s piano sonatas</a></td><td>Craig Stuart Sapp</td><td>public domain music, the encoding its editor&#39;s</td><td>Piano</td><td><code>haydn-piano-sonatas</code></td></tr><tr><td><a href="https://github.com/craigsapp/mozart-piano-sonatas" target="_blank" rel="noreferrer">Mozart&#39;s piano sonatas</a></td><td>Craig Stuart Sapp</td><td>public domain music, the encoding its editor&#39;s</td><td>Piano</td><td><code>mozart-piano-sonatas</code></td></tr><tr><td><a href="https://github.com/craigsapp/beethoven-piano-sonatas" target="_blank" rel="noreferrer">Beethoven&#39;s piano sonatas</a></td><td>Craig Stuart Sapp</td><td>public domain music, the encoding its editor&#39;s</td><td>Piano</td><td><code>beethoven-piano-sonatas</code></td></tr><tr><td><a href="https://github.com/craigsapp/beethoven-string-quartets" target="_blank" rel="noreferrer">Beethoven&#39;s string quartets</a></td><td>Craig Stuart Sapp</td><td>public domain music, the encoding its editor&#39;s</td><td>Strings</td><td><code>beethoven-string-quartets</code></td></tr><tr><td><a href="https://github.com/craigsapp/art-of-the-fugue" target="_blank" rel="noreferrer">Bach&#39;s Art of Fugue</a></td><td>Craig Stuart Sapp</td><td>public domain music, the encoding its editor&#39;s</td><td>Counterpoint</td><td><code>bach-art-of-fugue</code></td></tr><tr><td><a href="https://github.com/craigsapp/vivaldi-op6" target="_blank" rel="noreferrer">Vivaldi&#39;s Opus 6</a></td><td>Craig Stuart Sapp</td><td>public domain music, the encoding its editor&#39;s</td><td>Concertos</td><td><code>vivaldi-op6</code></td></tr><tr><td><a href="https://doi.org/10.18130/V3/C4RD06" target="_blank" rel="noreferrer">Public Domain Song Anthology</a></td><td>David Berger and Chuck Israels, University of Virginia</td><td>CC0</td><td>Lead sheets of songs out of copyright</td><td><code>song-anthology</code></td></tr><tr><td><a href="https://github.com/adactio/TheSession-data" target="_blank" rel="noreferrer">The Session&#39;s tunes</a></td><td>The Session</td><td>published openly for reuse; the tunes are traditional</td><td>Traditional dance tunes</td><td><code>thesession</code></td></tr></tbody></table><h3 id="downloading-the-corpus" tabindex="-1">Downloading the Corpus <a class="header-anchor" href="#downloading-the-corpus" aria-label="Permalink to &quot;Downloading the Corpus&quot;">​</a></h3><p>The corpus is downloaded only by a person who wants it, for study, into <code>output/corpus/</code>, which git ignores; nothing downloaded is committed or passed on. From llamatron&#39;s top folder:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/fetch_corpus.sh                 # asks collection by collection, with each one&#39;s size and terms</span></span>
<span class="line"><span>sh user_scripts/fetch_corpus.sh joplin thesession   # only the named collections</span></span></code></pre></div><p>A collection is named by its folder in the table above, such as <code>joplin</code> or <code>thesession</code>. The script asks before each download. <a href="./USER_SCRIPTS">User Scripts</a> describes the script.</p>`,15)])])}const m=e(d,[["render",o]]);export{u as __pageData,m as default};
